import{_ as i,a0 as o,w as s,s as u,I as e,x as t,a1 as r,A as n,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"GNOME 2 的 Linux 文件管理器 Caja | LCTT x X-CMD","titleTemplate":false,"description":"GNOME 2 的 Linux 文件管理器 Caja | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GNOME 2 的 Linux 文件管理器 Caja | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GNOME 2 的 Linux 文件管理器 Caja | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20221210.0 ⭐️ How to use the Linux file manager for GNOME 2","title":"GNOME 2 的 Linux 文件管理器 Caja","tag":"202302","desc":""},"relativePath":"202302/20221210.0 ⭐️ How to use the Linux file manager for GNOME 2.md","filePath":"[post].md"}'),m={name:"202302/20221210.0 ⭐️ How to use the Linux file manager for GNOME 2.md"};function d(f,a,j,C,x,g){const l=o("Link");return s(),u("div",null,[a[23]||(a[23]=e("h1",{id:"gnome-2-的-linux-文件管理器-caja",tabindex:"-1"},[t("GNOME 2 的 Linux 文件管理器 Caja "),e("a",{class:"header-anchor",href:"#gnome-2-的-linux-文件管理器-caja","aria-label":"Permalink to “GNOME 2 的 Linux 文件管理器 Caja”"},"​")],-1)),a[24]||(a[24]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/202302/12/093538qnlj0jdunz10n17c.jpg",alt:""})],-1)),a[25]||(a[25]=e("blockquote",null,[e("p",null,"如果你是 GNOME 2 的粉絲，那麼你肯定會發現 Caja 很熟悉，如果你從來沒有使用過 GNOME 2，那麼你可能會在 Mate 中找到你的新寵桌面。")],-1)),e("p",null,[a[1]||(a[1]=t("在 GNOME 3 之前是 GNOME 2（廢話），在其作為常見的默認 Linux 桌面之一的統治期間，它擁有了一個熱心的粉絲羣。",-1)),r(l,{href:"https://opensource.com/article/19/12/mate-linux-desktop"},{default:n(()=>[...a[0]||(a[0]=[t("Mate 項目",-1)])]),_:1}),a[2]||(a[2]=t("（以植物 ",-1)),a[3]||(a[3]=e("em",null,"yerba mate",-1)),a[4]||(a[4]=t(" 命名）最初是為了延續 GNOME 2 桌面的生命力，它起初是使用 GTK 2（基於 GNOME 2 的工具包）開發的，後來升級為 GTK 3。該桌面包含了一個 Caja 文件管理器，這是一個簡單而強大的應用，可以幫助你分類和組織你的數據。",-1))]),a[26]||(a[26]=e("h3",{id:"安裝-caja",tabindex:"-1"},[t("安裝 Caja "),e("a",{class:"header-anchor",href:"#安裝-caja","aria-label":"Permalink to “安裝 Caja”"},"​")],-1)),a[27]||(a[27]=e("p",null,"Caja 並不完全是一個獨立的應用。它與 Mate 桌面緊密相連，所以要試用它，你必須安裝 Mate。",-1)),e("p",null,[a[6]||(a[6]=t("你可能會發現 Mate 包含在你的 Linux 發行版的倉庫中，或者你可以下載並安裝一個將 Mate 作為默認桌面的發行版。不過，在你安裝之前，要注意它是為了提供完整的桌面體驗，所以會和桌面一起安裝許多 Mate 應用。如果你運行一個不同的桌面，你可能會發現自己有多餘的應用（兩個 PDF 閲讀器，兩個媒體播放器，兩個文件管理器，等等）。要評估 Caja 不會對你的電腦做重大改動，可以使用 ",-1)),r(l,{href:"https://opensource.com/article/19/5/getting-started-gnome-boxes-virtualization"},{default:n(()=>[...a[5]||(a[5]=[t("GNOME Boxes",-1)])]),_:1}),a[7]||(a[7]=t(" 在虛擬機中安裝一個基於 Mate 的發行版。",-1))]),a[28]||(a[28]=p('<p><img src="https://opensource.com/sites/default/files/2022-10/caja.file%20manager.png" alt="Image of the  Caja file manager."></p><h3 id="清晰的佈局" tabindex="-1">清晰的佈局 <a class="header-anchor" href="#清晰的佈局" aria-label="Permalink to “清晰的佈局”">​</a></h3><p>你可能首先注意到的是 Caja 的清晰而直接的佈局。在 Caja 窗口的頂部有一個工具欄，上面有一些常用任務的按鈕。我喜歡這樣的設計。功能不是隱藏在右鍵菜單中，也不是隻有在操作後才能發現，更不是埋在菜單中。窗口的“顯而易見”的操作被直接列在上面。</p><p>主工具欄下面是位置欄。它顯示你當前的路徑，可以是一系列的按鈕，也可以是可編輯的文本。使用路徑左邊的 “<ruby>編輯<rt>Edit</rt></ruby>” 按鈕來切換它是否可編輯。</p><h3 id="可配置" tabindex="-1">可配置 <a class="header-anchor" href="#可配置" aria-label="Permalink to “可配置”">​</a></h3><p>對於 GNOME 2 或 Caja 的長期用户來説，主工具欄可能是多餘的，尤其是當你知道了調用常用操作的鍵盤快捷鍵後。這就是為什麼 Caja 的界面是可配置的。你可以從 “<ruby>查看<rt>View</rt></ruby>” 菜單中禁用 Caja 窗口的主要組件，包括：</p><ul><li>主工具條</li><li>位置欄</li><li>側面板</li><li>附加面板</li><li>狀態欄</li></ul><p>簡而言之，你可以按你的想法精簡 Caja。</p><p><img src="https://opensource.com/sites/default/files/2022-10/caja-minimal-layout.png" alt="Image of a minimal Caja layout."></p><h3 id="標記你的文件夾" tabindex="-1">標記你的文件夾 <a class="header-anchor" href="#標記你的文件夾" aria-label="Permalink to “標記你的文件夾”">​</a></h3><p>有些人是 “可視化” 人。他們喜歡根據自己對數據的看法來組織文件和文件夾，而不是根據計算機對數據的解釋。例如，如果對你來説最重要的兩個文件夾是<strong>音樂</strong>和<strong>工作</strong>，就很難讓計算機相信這兩者之間有任何關係。按字母順序兩者也排不到一起，而且每個文件夾的內容可能完全不同（一個是媒體文件，另一個是電子表格）。</p><h3 id="caja-提供了一些幫助" tabindex="-1">Caja 提供了一些幫助 <a class="header-anchor" href="#caja-提供了一些幫助" aria-label="Permalink to “Caja 提供了一些幫助”">​</a></h3><p>使用 Caja，你可以在一個窗口內手動放置目錄，Caja 會記住這個位置。更重要的是，Caja 有多種標誌可供你用作視覺標籤。你可以在 “<ruby>編輯<rt>Edit</rt></ruby>” 菜單的 “<ruby>背景和標誌<rt>Backgrounds and Emblems</rt></ruby>” 中找到它們。將它們拖放到文件和文件夾中以幫助它們區分。</p><p><img src="https://opensource.com/sites/default/files/2022-10/caja-emblem.webp" alt="Image of emblems in Caja."></p><h3 id="caja" tabindex="-1">Caja <a class="header-anchor" href="#caja" aria-label="Permalink to “Caja”">​</a></h3><p>Caja 是最誘人的文件管理器之一。它的可配置性足以吸引許多不同的使用場景，而且在這些配置選項中，你很可能找到適合你的工作流程。如果你是 GNOME 2 的粉絲，那麼你肯定會發現 Caja 很熟悉，如果你從來沒有使用過 GNOME 2，那麼你可能會在 Mate 中找到你的新寵桌面。</p><hr>',17)),e("p",null,[a[9]||(a[9]=t("via: ",-1)),r(l,{href:"https://opensource.com/article/22/12/linux-file-manager-caja"},{default:n(()=>[...a[8]||(a[8]=[t("https://opensource.com/article/22/12/linux-file-manager-caja",-1)])]),_:1})]),e("p",null,[a[14]||(a[14]=t("作者：",-1)),r(l,{href:"https://opensource.com/users/seth"},{default:n(()=>[...a[10]||(a[10]=[t("Seth Kenlon",-1)])]),_:1}),a[15]||(a[15]=t(" 選題：",-1)),r(l,{href:"https://github.com/lkxed"},{default:n(()=>[...a[11]||(a[11]=[t("lkxed",-1)])]),_:1}),a[16]||(a[16]=t(" 譯者：",-1)),r(l,{href:"https://github.com/geekpi"},{default:n(()=>[...a[12]||(a[12]=[t("geekpi",-1)])]),_:1}),a[17]||(a[17]=t(" 校對：",-1)),r(l,{href:"https://github.com/wxy"},{default:n(()=>[...a[13]||(a[13]=[t("wxy",-1)])]),_:1})]),e("p",null,[a[20]||(a[20]=t("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...a[18]||(a[18]=[t("LCTT",-1)])]),_:1}),a[21]||(a[21]=t(" 原創編譯，",-1)),r(l,{href:"https://linux.cn/"},{default:n(()=>[...a[19]||(a[19]=[t("Linux中國",-1)])]),_:1}),a[22]||(a[22]=t(" 榮譽推出",-1))])])}const E=i(m,[["render",d]]);export{N as __pageData,E as default};
